                    "not_executed"
                  ]
                },
                "note": {
                  "type": "string",
                  "minLength": 10
                }
              }
            }
          }
        }
      }
    },
    "labs": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/lab"
      },
      "description": "The curriculum defines how many labs exist. The schema does not fix a count — it requires at least one lab, ascending, contiguous from L01, with unique ids."
    },
